insert into public.question_solutions (question_id, final_answer_markdown, explanation_markdown) values ('40000000-0000-4000-8000-000000006602', '$a_n/b_n\to3$; a série de $a_n$ converge.', 'A razão é $(3n^3+n^2)/(n^3+2)$ e tende a $3$. Esse limite é positivo e finito; as duas séries têm o mesmo comportamento. Como $\sum1/n^2$ converge, a série proposta também converge.') on conflict do nothing;
